 {shareUrl&&<div className="modal-backdrop" onMouseDown={()=>setShareUrl('')}><section className="modal share-dialog" onMouseDown={e=>e.stopPropagation()}><div className="modal-title"><h2>{shareKind==='live'?'Share live trip':'Share snapshot'}</h2><button type="button" className="close" onClick={()=>setShareUrl('')}>×</button></div><p>{shareKind==='live'?(active.archivedAt?'Anyone with this link can connect Google Drive and view the archived itinerary.':'Anyone with this link can connect Google Drive, edit the same trip, and receive merged updates.'):'This read-only link contains a fixed copy of the trip and will not receive later changes.'}</p><label>Share link<div className="share-link-field"><input ref={shareRef} readOnly value={shareUrl} onFocus={e=>e.currentTarget.select()}/><button type="button" title="Copy to clipboard" aria-label="Copy share link to clipboard" onClick={async()=>{if(await copyText(shareUrl))setShareCopyStatus('Copied to clipboard.');else{shareRef.current?.select();setShareCopyStatus('Select the link and use your browser’s Copy command.')}}}><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="8" y="8" width="11" height="12" rx="2"/><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h2"/></svg></button></div></label><p className="share-copy-status" role="status">{shareCopyStatus}</p><div className="modal-actions"><span/><button type="button" className="secondary" onClick={()=>setShareUrl('')}>Done</button></div></section></div>}
 {calendarUrl&&<div className="modal-backdrop" onMouseDown={()=>setCalendarUrl('')}><section className="modal share-dialog calendar-dialog" onMouseDown={e=>e.stopPropagation()}><div className="modal-title"><h2>Calendar subscription</h2><button type="button" className="close" aria-label="Close calendar subscription" onClick={()=>setCalendarUrl('')}>×</button></div><p>Copy this public read-only URL into your calendar app. In Google Calendar on a computer, choose <strong>Other calendars → Add → From URL</strong>. It appears as a separate subscribed calendar; Google controls when updates are retrieved.</p><label>Subscription URL<div className="share-link-field"><input ref={calendarRef} autoFocus readOnly value={calendarUrl} onFocus={e=>e.currentTarget.select()}/><button type="button" title="Copy to clipboard" aria-label="Copy calendar subscription URL" onClick={async()=>{if(await copyText(calendarUrl))setCalendarCopyStatus('Copied to clipboard.');else{calendarRef.current?.select();setCalendarCopyStatus('Select the URL and use your browser’s Copy command.')}}}><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="8" y="8" width="11" height="12" rx="2"/><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h2"/></svg></button></div></label><p className="share-copy-status" role="status">{calendarCopyStatus}</p><div className="modal-actions"><span/><a className="calendar-feed-link" href={calendarUrl} target="_blank" rel="noreferrer">Open current feed ↗</a><button type="button" className="secondary" onClick={()=>setCalendarUrl('')}>Done</button></div></section></div>}
